import { readFileSync, readdirSync } from "node:fs";
const files = readdirSync("rules").filter((f) => f.endsWith(".md"));
const short = (f: string) => f.replace(".md", "").replace("NodeJS", "N").replace("Bun", "B").replace("+React", "+R").replace("+Tailwind", "+T");
const want = process.argv.slice(2);
const secs = new Map<string, Map<string, string[]>>();
for (const f of files) {
  const raw = readFileSync(`rules/${f}`, "utf8");
  for (const p of raw.split(/^## /m).slice(1)) {
    const title = p.split("\n")[0].trim();
    if (!secs.has(title)) secs.set(title, new Map());
    secs.get(title)!.set(f, p.split("\n").slice(1).filter((l) => l.trim().startsWith("- ")).map((l) => l.trim()));
  }
}
for (const [title, m] of secs) {
  if (!want.some((w) => title.startsWith(w))) continue;
  const all = [...new Set([...m.values()].flat())];
  const partial = all.filter((line) => {
    const have = files.filter((f) => m.get(f)?.includes(line));
    return have.length > 0 && have.length < m.size;
  });
  if (!partial.length) continue;
  console.log(`\n### ${title}`);
  for (const line of partial) {
    const have = files.filter((f) => m.get(f)?.includes(line)).map(short);
    console.log(`  [${have.join(", ")}]`.padEnd(30) + line.slice(0, 96));
  }
}
EOF
